#include "sfn_update_guard.h"
#include "ota_hash.h"
#include "ota_guard.h"
#include <string.h>
#define UPDATE_MAGIC 0x32475553u /* SUG2 */
#define RECORD_BYTES 124u
#define ATTEMPTS_OFF 16u
#define TRUSTED_OFF 20u
#define BACKUP_SHA_OFF 28u
#define IMAGE_SHA_OFF 60u
#define RECORD_SHA_OFF 92u
#define ATTEMPT_LIMIT 2u
static uint32_t le32(const uint8_t *p){return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
static void put32(uint8_t *p,uint32_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);p[2]=(uint8_t)(v>>16);p[3]=(uint8_t)(v>>24);}
static int read_exact(const sfn_boot_guard_io *io,uint32_t a,uint8_t *p,size_t n){return io&&io->read&&p&&n&&io->read(io->context,a,p,n)==1;}
static int write_exact(const sfn_boot_guard_io *io,uint32_t a,const uint8_t *p,size_t n){uint8_t check[256];size_t pos=0,k;if(!io||!io->write||!p||!n)return 0;while(pos<n){k=n-pos;if(k>sizeof(check))k=sizeof(check);if(io->write(io->context,a+pos,p+pos,k)!=1||!read_exact(io,a+pos,check,k)||memcmp(check,p+pos,k))return 0;pos+=k;}return 1;}
static int sector_blank(const sfn_boot_guard_io *io,uint32_t a){uint8_t b[256];unsigned i,j;for(i=0;i<4096;i+=sizeof(b)){if(!read_exact(io,a+i,b,sizeof(b)))return 0;for(j=0;j<sizeof(b);j++)if(b[j]!=255)return 0;}return 1;}
static int erase_blank(const sfn_boot_guard_io *io,uint32_t a){return io&&io->erase_sector&&io->erase_sector(io->context,a)==1&&sector_blank(io,a);}
static uint32_t metadata_sector(const sfn_boot_guard_descriptor *d,uint32_t slot){return slot==d->first?d->second-8192u:slot==d->second?d->guard_sector-8192u:0;}
static uint32_t backup_sector(const sfn_boot_guard_descriptor *d,uint32_t slot){return slot==d->first?d->second-4096u:slot==d->second?d->guard_sector-4096u:0;}
static int hash_finish_bytes(const uint8_t *p,size_t n,uint8_t out[32]){mttl_ota_hash h;mttl_ota_hash_init(&h);return mttl_ota_hash_update(&h,p,n)&&mttl_ota_hash_finish(&h,out);}
static int image_header(const sfn_boot_guard_descriptor *d,const sfn_boot_guard_io *io,uint32_t slot,uint32_t *bytes){uint8_t h[40];uint32_t body,limit;if(!read_exact(io,slot,h,sizeof(h)))return 0;body=le32(h);if(body>0xffffffffu-20u)return 0;*bytes=body+20u;limit=metadata_sector(d,slot);if(!limit||*bytes<44u||*bytes>limit-slot)return 0;memset(h+8,255,8);return mttl_ota_header_validate(h,sizeof(h),*bytes);}
static int image_hash(const sfn_boot_guard_descriptor *d,const sfn_boot_guard_io *io,uint32_t slot,uint32_t bytes,const uint8_t *first_sector,uint8_t out[32]){mttl_ota_hash h;uint8_t b[256];uint32_t pos=0;unsigned i;(void)d;mttl_ota_hash_init(&h);while(pos<bytes){size_t n=bytes-pos;if(n>sizeof(b))n=sizeof(b);if(first_sector&&pos<4096u){memcpy(b,first_sector+pos,n);}else if(!read_exact(io,slot+pos,b,n)){(void)mttl_ota_hash_finish(&h,out);return 0;}for(i=0;i<n;i++){uint32_t at=pos+i;if(at>=8u&&at<16u)b[i]=255;}if(!mttl_ota_hash_update(&h,b,n)){(void)mttl_ota_hash_finish(&h,out);return 0;}pos+=(uint32_t)n;}return mttl_ota_hash_finish(&h,out);}
static int image_signature(const sfn_boot_guard_io *io,uint32_t slot){uint8_t b[8];return read_exact(io,slot+8,b,sizeof(b))?mttl_ota_signature(b):MTTL_OTA_INVALID;}
static int image_hardware_ok(const sfn_boot_guard_io *io,uint32_t slot){static const uint8_t expected[32]="LGU+-TAP-HW002";uint8_t actual[32];return read_exact(io,slot+0x28u,actual,sizeof(actual))&&!memcmp(actual,expected,sizeof(actual));}
static int image_checksum_ok(const sfn_boot_guard_io *io,uint32_t slot,uint32_t bytes){static const uint8_t new_sig[8]="81958711",old_sig[8]="01958711";uint8_t b[256],tail[4];uint32_t pos=0,sum=0,stored;unsigned i;uint32_t new_sum=0,old_sum=0;if(bytes<44u||!read_exact(io,slot+bytes-4u,tail,sizeof(tail)))return 0;while(pos<bytes-4u){size_t n=bytes-4u-pos;if(n>sizeof(b))n=sizeof(b);if(!read_exact(io,slot+pos,b,n))return 0;for(i=0;i<n;i++){uint32_t at=pos+i;if(at<8u||at>=16u)sum+=b[i];}pos+=(uint32_t)n;}for(i=0;i<8u;i++){new_sum+=new_sig[i];old_sum+=old_sig[i];}stored=le32(tail);return stored==sum+2040u||stored==sum+new_sum||stored==sum+old_sum;}
static int first_flash_previous_ok(const sfn_boot_guard_descriptor *d,const sfn_boot_guard_io *io,uint32_t slot,uint32_t *bytes){uint32_t n;if(image_signature(io,slot)!=MTTL_OTA_OLD||!image_header(d,io,slot,&n)||!image_hardware_ok(io,slot)||!image_checksum_ok(io,slot,n))return 0;*bytes=n;return 1;}
static int sector_compatible(const sfn_boot_guard_io *io,uint32_t address,const uint8_t *expected,size_t expected_bytes){uint8_t b[256];uint32_t pos=0;unsigned i;while(pos<4096u){size_t n=4096u-pos;if(n>sizeof(b))n=sizeof(b);if(!read_exact(io,address+pos,b,n))return 0;for(i=0;i<n;i++){uint8_t want=(pos+i<expected_bytes)?expected[pos+i]:255u;if((b[i]&want)!=want)return 0;}pos+=(uint32_t)n;}return 1;}
static int record_hash(uint8_t record[RECORD_BYTES],uint8_t out[32]){uint8_t copy[RECORD_SHA_OFF];memcpy(copy,record,sizeof(copy));memset(copy+ATTEMPTS_OFF,255,8);return hash_finish_bytes(copy,sizeof(copy),out);}
static int record_valid_at(const sfn_boot_guard_descriptor *d,const sfn_boot_guard_io *io,uint32_t meta,uint8_t record[RECORD_BYTES]){uint8_t digest[32];uint32_t p,c,b;if(!read_exact(io,meta,record,RECORD_BYTES)||le32(record)!=UPDATE_MAGIC)return 0;p=le32(record+4);c=le32(record+8);b=le32(record+12);if(!((p==d->first&&c==d->second)||(p==d->second&&c==d->first))||b!=backup_sector(d,p)||meta!=metadata_sector(d,p))return 0;if(!record_hash(record,digest)||memcmp(digest,record+RECORD_SHA_OFF,32))return 0;return 1;}
static int find_record(const sfn_boot_guard_descriptor *d,const sfn_boot_guard_io *io,uint32_t current,uint8_t out[RECORD_BYTES],uint32_t *meta){uint8_t a[RECORD_BYTES],b[RECORD_BYTES];uint32_t ma=metadata_sector(d,d->first),mb=metadata_sector(d,d->second);int av=record_valid_at(d,io,ma,a),bv=record_valid_at(d,io,mb,b);if(av&&le32(a+8)==current){memcpy(out,a,sizeof(a));*meta=ma;return 1;}if(bv&&le32(b+8)==current){memcpy(out,b,sizeof(b));*meta=mb;return 1;}if(av&&le32(a+4)==current){memcpy(out,a,sizeof(a));*meta=ma;return 1;}if(bv&&le32(b+4)==current){memcpy(out,b,sizeof(b));*meta=mb;return 1;}return 0;}
int sfn_update_guard_locate_current(const sfn_boot_guard_descriptor *d,const sfn_boot_guard_io *io,uint32_t *current){uint8_t a[64],b[64];int av,bv;if(!d||!io||!current||!d->marker||!d->marker_size||d->marker_size>sizeof(a))return 0;if(!read_exact(io,d->first+d->marker_offset,a,d->marker_size)||!read_exact(io,d->second+d->marker_offset,b,d->marker_size))return 0;av=!memcmp(a,d->marker,d->marker_size);bv=!memcmp(b,d->marker,d->marker_size);if(av==bv)return 0;*current=av?d->first:d->second;return 1;}
static int backup_ok(const sfn_boot_guard_io *io,uint32_t backup,const uint8_t expected[32]){mttl_ota_hash h;uint8_t b[256],digest[32];uint32_t pos=0;mttl_ota_hash_init(&h);while(pos<4096u){if(!read_exact(io,backup+pos,b,sizeof(b))||!mttl_ota_hash_update(&h,b,sizeof(b))){(void)mttl_ota_hash_finish(&h,digest);return 0;}pos+=sizeof(b);}return mttl_ota_hash_finish(&h,digest)&&!memcmp(digest,expected,32);}
static int previous_material_ok(const sfn_boot_guard_descriptor *d,const sfn_boot_guard_io *io,const uint8_t record[RECORD_BYTES]){uint8_t first[4096],digest[32],h[40];uint32_t p=le32(record+4),backup=le32(record+12),bytes=le32(record+24);if(!backup_ok(io,backup,record+BACKUP_SHA_OFF)||!read_exact(io,backup,first,sizeof(first)))return 0;memcpy(h,first,sizeof(h));memset(h+8,255,8);if(!mttl_ota_header_validate(h,sizeof(h),bytes)||bytes>metadata_sector(d,p)-p)return 0;if(!image_hash(d,io,p,bytes,first,digest)||memcmp(digest,record+IMAGE_SHA_OFF,32))return 0;return 1;}
static unsigned cleared(uint32_t v){unsigned n=0;while(v!=0xffffffffu){n+=(~v)&1u;v=(v>>1)|0x80000000u;}return n;}
static int clear_attempt(const sfn_boot_guard_io *io,uint32_t meta,uint32_t attempts){uint8_t b[4];unsigned n=cleared(attempts);uint32_t next;if(n>=32)return 0;next=attempts&~(1u<<n);put32(b,next);return write_exact(io,meta+ATTEMPTS_OFF,b,4);}
static int set_old_signature(const sfn_boot_guard_io *io,uint32_t slot){uint8_t old[4]={'0','1','9','5'},before[4];if(!read_exact(io,slot+8,before,4))return 0;if(!memcmp(before,old,4))return 1;return write_exact(io,slot+8,old,4);}
int sfn_update_guard_prepare(const sfn_boot_guard_descriptor *d,const sfn_boot_guard_io *io,uint32_t previous,uint32_t candidate){uint8_t record[RECORD_BYTES],chunk[256],check[256],backup_sha[32],image_sha[32];uint32_t bytes,meta,backup,pos,current;size_t n;if(!d||!io||!((previous==d->first&&candidate==d->second)||(previous==d->second&&candidate==d->first))||!sfn_update_guard_locate_current(d,io,&current)||current!=previous)return 0;meta=metadata_sector(d,previous);backup=backup_sector(d,previous);if(!meta||!backup||!image_header(d,io,previous,&bytes))return 0;if(!image_hash(d,io,previous,bytes,0,image_sha))return 0;if(!erase_blank(io,backup))return 0;for(pos=0;pos<4096u;pos+=(uint32_t)n){n=4096u-pos;if(n>sizeof(chunk))n=sizeof(chunk);if(!read_exact(io,previous+pos,chunk,n)||!write_exact(io,backup+pos,chunk,n)||!read_exact(io,backup+pos,check,n)||memcmp(chunk,check,n))return 0;}
 {mttl_ota_hash h;mttl_ota_hash_init(&h);for(pos=0;pos<4096u;pos+=sizeof(chunk)){if(!read_exact(io,backup+pos,chunk,sizeof(chunk))||!mttl_ota_hash_update(&h,chunk,sizeof(chunk)))return 0;}if(!mttl_ota_hash_finish(&h,backup_sha))return 0;}
 memset(record,255,sizeof(record));put32(record,UPDATE_MAGIC);put32(record+4,previous);put32(record+8,candidate);put32(record+12,backup);put32(record+24,bytes);memcpy(record+BACKUP_SHA_OFF,backup_sha,32);memcpy(record+IMAGE_SHA_OFF,image_sha,32);if(!record_hash(record,record+RECORD_SHA_OFF))return 0;if(!erase_blank(io,meta)||!write_exact(io,meta,record,sizeof(record)))return 0;{uint8_t verify[RECORD_BYTES];if(!record_valid_at(d,io,meta,verify))return 0;}
 /* Remove the stale record belonging to the inactive slot only after the new
  * record is durably verified, so power loss always leaves at least one truth. */
 {uint32_t stale=metadata_sector(d,candidate);if(stale&&stale!=meta&&!sector_blank(io,stale)&&!erase_blank(io,stale))return 0;}return 1;}
int sfn_update_guard_adopt_first_flash(const sfn_boot_guard_descriptor *d,const sfn_boot_guard_io *io,uint32_t candidate){uint8_t record[RECORD_BYTES],first[4096],backup[4096],backup_sha[32],image_sha[32];uint32_t current,previous,bytes,meta,backup_at;if(!d||!io||!sfn_update_guard_locate_current(d,io,&current)||current!=candidate||image_signature(io,candidate)!=MTTL_OTA_NEW)return 0;previous=candidate==d->first?d->second:candidate==d->second?d->first:0;if(!previous||!first_flash_previous_ok(d,io,previous,&bytes)||!read_exact(io,previous,first,sizeof(first)))return 0;meta=metadata_sector(d,previous);backup_at=backup_sector(d,previous);if(!meta||!backup_at||bytes>meta-previous)return 0;memcpy(backup,first,sizeof(backup));memcpy(backup+8,"81958711",8);if(!hash_finish_bytes(backup,sizeof(backup),backup_sha)||!image_hash(d,io,previous,bytes,0,image_sha))return 0;memset(record,255,sizeof(record));put32(record,UPDATE_MAGIC);put32(record+4,previous);put32(record+8,candidate);put32(record+12,backup_at);put32(record+24,bytes);memcpy(record+BACKUP_SHA_OFF,backup_sha,32);memcpy(record+IMAGE_SHA_OFF,image_sha,32);if(!record_hash(record,record+RECORD_SHA_OFF))return 0;
 /* Before claiming spare sectors, require them to be either erased or a bitwise-compatible partial write of this exact adoption. This makes interrupted first-boot adoption retryable without erasing unknown stock data. */
 if(!sector_compatible(io,backup_at,backup,sizeof(backup))||!sector_compatible(io,meta,record,sizeof(record)))return 0;
 if(!write_exact(io,backup_at,backup,sizeof(backup))||!write_exact(io,meta,record,sizeof(record)))return 0;
 {uint8_t verify[RECORD_BYTES];if(!record_valid_at(d,io,meta,verify)||!previous_material_ok(d,io,verify))return 0;}
 return 1;}
int sfn_update_guard_start(sfn_update_guard_state *s,const sfn_boot_guard_descriptor *d,const sfn_boot_guard_io *io,uint32_t current,uint32_t now){uint8_t record[RECORD_BYTES];uint32_t meta,previous,candidate,attempts,trusted;if(!s||!d||!io)return SFN_UPDATE_GUARD_FAILED;memset(s,0,sizeof(*s));if(!find_record(d,io,current,record,&meta))return SFN_UPDATE_GUARD_NONE;previous=le32(record+4);candidate=le32(record+8);attempts=le32(record+ATTEMPTS_OFF);trusted=le32(record+TRUSTED_OFF);s->previous_slot=previous;s->candidate_slot=candidate;s->metadata_sector=meta;s->backup_sector=le32(record+12);s->started_ms=now;if(current==previous){if(!set_old_signature(io,candidate))return SFN_UPDATE_GUARD_FAILED;s->trusted=1;return SFN_UPDATE_GUARD_TRUSTED;}if(current!=candidate||!previous_material_ok(d,io,record))return SFN_UPDATE_GUARD_FAILED;s->current_is_candidate=1;s->available=1;if(trusted==0){s->trusted=1;return SFN_UPDATE_GUARD_TRUSTED;}if(cleared(attempts)>=ATTEMPT_LIMIT){s->armed=1;return SFN_UPDATE_GUARD_ROLLBACK_READY;}if(!clear_attempt(io,meta,attempts))return SFN_UPDATE_GUARD_FAILED;s->armed=1;return SFN_UPDATE_GUARD_ARMED;}
int sfn_update_guard_mark_trusted(sfn_update_guard_state *s,const sfn_boot_guard_descriptor *d,const sfn_boot_guard_io *io){uint8_t zero[4]={0,0,0,0};(void)d;if(!s||!s->armed||!s->current_is_candidate||s->trusted||!io)return 0;if(!write_exact(io,s->metadata_sector+TRUSTED_OFF,zero,4))return 0;s->trusted=1;s->armed=0;return 1;}
int sfn_update_guard_should_timeout(const sfn_update_guard_state *s,uint32_t now,uint32_t timeout){return s&&s->armed&&!s->trusted&&timeout&&((uint32_t)(now-s->started_ms)>=timeout);}
int sfn_update_guard_rollback(sfn_update_guard_state *s,const sfn_boot_guard_descriptor *d,const sfn_boot_guard_io *io){uint8_t record[RECORD_BYTES],chunk[256],check[256];uint32_t pos;if(!s||!s->available||!s->current_is_candidate||!record_valid_at(d,io,s->metadata_sector,record)||!previous_material_ok(d,io,record))return 0;if(!erase_blank(io,s->previous_slot))return 0;for(pos=0;pos<4096u;pos+=sizeof(chunk)){if(!read_exact(io,s->backup_sector+pos,chunk,sizeof(chunk))||!write_exact(io,s->previous_slot+pos,chunk,sizeof(chunk))||!read_exact(io,s->previous_slot+pos,check,sizeof(check))||memcmp(chunk,check,sizeof(chunk)))return 0;}if(!set_old_signature(io,s->candidate_slot))return 0;return 1;}
